insert into product (id, name, description, img_url, price, type_name, category_name) values (45, 'Baby''s First Block', 'He''ll be building block towers soon enough! For now, celebrate him with this beautiful keepsake baby block. Filled with soft blues and whites, the glass block can be used later in baby''s room.', 'https://img.teleflora.com/images/o_0/l_flowers:T34-2C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T34-2C/Baby''sFirstBlockbyTeleflora-BluePM', 1725000, 'DELPHINIUMS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (46, 'Turn Up The Pink Bouquet', 'Pop goes the pink! A gorgeously chic gift for any occasion, this perky pink and orange bouquet is pure fun, especially when it''s hand-delivered in our fabulous fuchsia Cube!', 'https://img.teleflora.com/images/o_0/l_flowers:TEV33-1C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/TEV33-1C/Teleflora''sTurnUpThePinkBouquetPM', 1840000, 'GERBERAS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (47, 'Brilliant Birthday Blooms', 'There''s no mistaking this bouquet for anything but a Happy Birthday wish! With its colorful streamers and birthday candle design, this bright arrangement is perfect as a great party centerpiece.', 'https://img.teleflora.com/images/o_0/l_flowers:T28-1C,pg_6/w_368,h_460,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T28-1C/Teleflora''sBrilliantBirthdayBloomsPM', 1495000, 'GERBERAS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (48, 'Rainbow Rays Potted Gerbera', 'In living color! Send them a lovely, long-lasting gift with this potted red gerbera daisy plant. An exceptional value, the happy houseplant is presented in a red-glazed terra-cotta pot that can be used to brighten up.', 'https://img.teleflora.com/images/o_0/l_flowers:T95-5A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T95-5A/RainbowRaysPottedGerbera-Red', 690000, 'GERBERAS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (49, 'Ticket to Paradise', 'As lush and serene as a tropical sunset, this paradise of feminine blooms is a unique way to send your best wishes. The well-balanced arrangement is both chic and Zen, with its graceful callas.', 'https://img.teleflora.com/images/o_0/l_flowers:T81-3A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T81-3A/Teleflora''sTickettoParadise', 2760000, 'HYDRANGEAS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (50, 'Happy Hydrangea', 'Have you ever seen a happier plant? The hydrangea''s beautiful, billowing blooms are beloved by all. Send this 6-inch potted blue hydrangea plant as a housewarming gift or simply to brighten someone''s day with a living gift.', 'https://img.teleflora.com/images/o_0/l_flowers:T89-2A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T89-2A/HappyHydrangea-Blue', 1610000, 'HYDRANGEAS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (51, 'Everything''s Beachy', 'What''s more beachy than a bouquet that comes with a built-in beach? This delightful summer arrangement is delivered in an acrylic vase that has an invisible panel holding a beach scene of seashells.', 'https://img.teleflora.com/images/o_0/l_flowers:T163-3A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T163-3A/Everything''sBeachybyTeleflora', 2185000, 'HYDRANGEAS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (52, 'Spring Favorites', 'Roses and tulips and hyacinth - oh, my! All your spring favorites are here, whimsically arranged in a shallow terra-cotta pot in pretty pastel spring colors. The fun potted flower arrangement is a wonderful way to welcome a new baby.', 'https://img.teleflora.com/images/o_0/l_flowers:T149-1C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T149-1C/SpringFavoritesPM', 2070000, 'IRISES', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (53, 'Fairest of All', 'A fairy tale…in flowers! Delicate ivy climbs the handle of this round wicker basket that''s home to a feminine garden of fuchsia flowers. You can almost imagine garden sprites dancing through the country style arrangement!', 'https://img.teleflora.com/images/o_0/l_flowers:T147-3B,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T147-3B/FairestofAllDX', 1955000, 'LISIANTHUS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (54, 'Napa Valley Centerpiece', 'Invite the natural beauty and wonder of Napa Valley to your wedding! This beautiful white flower centerpiece delivers innocence and elegance along with a stunning array of white blossoms and graceful greens.', 'https://img.teleflora.com/images/o_0/l_flowers:T198-1A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T198-1A/Teleflora''sNapaValleyCenterpiece', 3220000, 'LISIANTHUS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (55, 'Breathless Bouquet', 'Go all-out for style with this stunning silver vase filled with lavender roses and other lush blooms, and crowned by a snow-white orchid. She''ll appreciate your impeccable taste and love the way you show your love for her.', 'https://img.teleflora.com/images/o_0/l_flowers:T403-2B,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T403-2B/Teleflora''sBreathlessBouquetDX', 2415000, 'LISIANTHUS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (56, 'Pretty in Peony', 'Good and girly! A fabulous pick for a stylish sister, friend or girlfriend, this trendy peony bouquet pairs lush, cloud-white hydrangea with the luscious beauty of pink peonies.', 'https://img.teleflora.com/images/o_0/l_flowers:T145-2C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T145-2C/Teleflora''sPrettyinPeonyPM', 2070000, 'PEONIES', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (57, 'Perfect Peonies', 'Peony perfection! Everyone loves the lush, cloud-like appearance of fresh cut peonies. The romantic, feminine bloom is a popular summer wedding flower.', 'https://img.teleflora.com/images/o_0/l_flowers:T144-1C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T144-1C/Teleflora''sPerfectPeoniesPM', 3105000, 'PEONIES', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (58, 'Serene Spring Peony Bouquet', 'Chic and serene, this dreamy bouquet of wondrous white peonies and creamy blooms in a milk jug vase sends your very best wishes for a stylish spring!', 'https://img.teleflora.com/images/o_0/l_flowers:TSP06-1C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/TSP06-1C/SereneSpringPeonyBouquetPM', 2760000, 'PEONIES', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (59, 'Love Everlasting Bouquet', 'Celebrate the beauty of a life fully lived with this lovely array of pink lilies, blue hydrangea and other floral favorites in a sparkling Ming urn.', 'https://img.teleflora.com/images/o_0/l_flowers:T267-1C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T267-1C/LoveEverlastingBouquetPM', 2990000, 'STOCK', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (60, 'Enchanted Cottage', 'As enchanting as coming across a hidden cottage in the countryside! Lush white roses and purple stock mix with delicate lavender waxflower and green pitta negra for an elegant English garden look.', 'https://img.teleflora.com/images/o_0/l_flowers:T50-1C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T50-1C/Teleflora''sEnchantedCottagePM', 1610000, 'STOCK', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (61, 'Joyful Memory', 'Lavender and white sympathy flowers make a grand statement in this joyful bouquet. Cherish your memories with this lasting remembrance of lavender larkspur and roses, deep purple asters.', 'https://img.teleflora.com/images/o_0/l_flowers:T251-1C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T251-1C/JoyfulMemoryPM', 3105000, 'STOCK', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (62, 'Love''s Tapestry', 'This stylish, uplifting mix of sympathy flowers for the service is bursting with color. The tall arrangement features an array of flowers that will touch everyone''s hearts, artistically arranged in a sympathy basket.', 'https://img.teleflora.com/images/o_0/l_flowers:T218-2A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T218-2A/Love''sTapestry', 2415000, 'SNAPDRAGONS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (63, 'Vivid Recollections', 'Send sunshine to show you care. A symbol of friendship, these yellow sympathy flowers are accented with pretty pink carnations for a classic sympathy basket that will warm anyone''s heart.', 'https://img.teleflora.com/images/o_0/l_flowers:T218-4A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T218-4A/VividRecollections', 1725000, 'SNAPDRAGONS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (64, 'Passionate Purple Tulips', 'Tulips this tantalizing need no decoration! Celebrate a spring birthday, send your love, or simply let someone know you''re thinking of them with this stunning monochrome bouquet.', 'https://img.teleflora.com/images/o_0/l_flowers:T148-2C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T148-2C/PassionatePurpleTulipsPM', 2415000, 'TULIPS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (65, 'Sweet Surrender Bouquet', 'Surrender to the elegant, natural beauty of tulips. Twenty five red and pink flowers are presented in our graceful Silver Reflections vase. It''s a premium presentation that highlights the tulips'' natural beauty.', 'https://img.teleflora.com/images/o_0/l_flowers:T402-1C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T402-1C/Teleflora''sSweetSurrenderBouquetPM', 2138000, 'TULIPS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (66, 'Sunny Yellow Tulips', 'Sunny yellow tulips are a sure sign of spring. Even if the weather is not cooperating, you can be sure the person who receives this bright bouquet will feel the warmth of your message.', 'https://img.teleflora.com/images/o_0/l_flowers:T140-1C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T140-1C/SunnyYellowTulipsPM', 2415000, 'TULIPS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (67, 'Exquisite Elegance Bouquet', 'A sculpture of blooms. Elevate any occasion with this exquisite masterpiece of elegant orchids, roses and graphic succulents, dripping with amaranthus and arranged in an oversized glass jug.', 'https://img.teleflora.com/images/o_0/l_flowers:TEV56-9C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/TEV56-9C/ExquisiteEleganceBouquetPM', 4025000, 'TROPICAL FLOWERS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (68, 'Regally Yours Orchid', 'Regally beautiful, this amazing orange cymbidium orhid plant in a gorgeous pot is a lovely, living gift that will make them smile every day! A stunning surprise for any occasion.', 'https://img.teleflora.com/images/o_0/l_flowers:TPL04-1A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/TPL04-1A/Teleflora''sRegallyYoursOrchid', 2530000, 'TROPICAL FLOWERS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (69, 'Fantasy Found', 'Minimalist beauty abounds in this unique mix of orchids, gladioli and leucadendron. Delivered in a large bamboo cube, it''s sure to impress men and women alike.', 'https://img.teleflora.com/images/o_0/l_flowers:T84-1A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T84-1A/Teleflora''sFantasyFound', 2415000, 'TROPICAL FLOWERS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (70, 'Summer Daydream Bouquet', 'A daydream come true, this bold bouquet is an instant dose of sunshine! Celebrate your special someone with sunny blooms arranged in our rich blue vase.', 'https://img.teleflora.com/images/o_0/l_flowers:TEV31-4C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/TEV31-4C/Teleflora''sSummerDaydreamBouquetPM', 1495000, 'MIXED BOUQUETS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (71, 'Blossoms in Vogue', 'High-fashion flowers for the style-minded! This modern presentation of multicolored roses and green hydrangea has a tropical feel thanks to the hot color palette and the aspidistra leaves in the vase.', 'https://img.teleflora.com/images/o_0/l_flowers:T74-1C,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T74-1C/BlossomsinVoguePM', 2185000, 'MIXED BOUQUETS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (72, 'Island Dreams', 'Exotic meets chic. Presented in a black glass cube, this artistic gift features bright, tropical blooms framed by folded red ti leaves. It''s an energizing choice for a man or woman.', 'https://img.teleflora.com/images/o_0/l_flowers:T85-2A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T85-2A/Teleflora''sIslandDreams', 2300000, 'MIXED BOUQUETS', 'FLOWERS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (73, 'Secret Garden Basket', 'Imagine walking into a secret fern grotto. This lush garden arrangement features the delicate fronds of maidenhair and Boston ferns mixed with colorful kalanchoe and pink hypoestes.', 'https://img.teleflora.com/images/o_0/l_flowers:T96-2A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T96-2A/SecretGardenBasket', 1610000, 'BLOOMING PLANTS', 'PLANTS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (74, 'Health Nut Basket', 'Healthy fruits and nuts are presented with a pretty potted kalanchoe plant in a large wicker basket. Health food has never looked so good!', 'https://img.teleflora.com/images/o_0/l_flowers:T108-2A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T108-2A/HealthNutBasket', 1725000, 'BLOOMING PLANTS', 'PLANTS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (75, 'Stylish Plant Assortment', 'A modern way to send mixed plants! This colorful, long-lasting gift is presented in a dark vase with clean lines, making it a perfect pick for the home or office. Also an excellent get-well gift!', 'https://img.teleflora.com/images/o_0/l_flowers:T106-3A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T106-3A/StylishPlantAssortment', 1840000, 'BLOOMING PLANTS', 'PLANTS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (76, 'Stately Croton', 'Not your typical houseplant! With its bright tropical foliage, exotic appearance and Asian-inspired square planter, this potted croton plant is an eye-catching natural addition to any room.', 'https://img.teleflora.com/images/o_0/l_flowers:T106-2A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T106-2A/StatelyCroton', 1725000, 'GREEN PLANTS', 'PLANTS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (77, 'Money Tree', 'Harmonize the five elements within a space, bring good fortune and prosperity, and improve the flow of "chi" with a money tree! The money tree - or Pachira - is thought to bring good luck.', 'https://img.teleflora.com/images/o_0/l_flowers:T12Z101A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T12Z101A/MoneyTree', 1150000, 'GREEN PLANTS', 'PLANTS') as v
insert into product (id, name, description, img_url, price, type_name, category_name) values (78, 'Peaceful Zen Garden', 'The gift of Zen. Send peace someone''s way with this elegant, eye-pleasing arrangement of low-maintenance succulent plants. Presented in a brown bamboo container, the plants are accented with smooth river rocks.', 'https://img.teleflora.com/images/o_0/l_flowers:T101-1A,pg_6/w_800,h_1000,cs_no_cmyk,c_pad/f_jpg,q_auto:eco,e_sharpen:200/flowers/T101-1A/Teleflora''sPeacefulZenGarden', 1380000, 'GREEN PLANTS', 'PLANTS') as v
